def count_Substrings(s, n):
    """Write a python function to count number of substrings with the sum of digits equal to their length."""
    if s is None:
        return 0
    if isinstance(s, int):
        s = str(s)
    if n is None:
        limit = len(s)
    else:
        limit = min(int(n), len(s))
    if limit <= 0:
        return 0
    # A substring has digit-sum == length iff the sum of (digit - 1)
    # over that substring is 0. Count equal prefix sums.
    counts = {0: 1}
    prefix = 0
    total = 0
    for i in range(limit):
        prefix += int(s[i]) - 1
        total += counts.get(prefix, 0)
        counts[prefix] = counts.get(prefix, 0) + 1
    return total
